   127	        if (reservation.status() != ReservationStatus.PENDING) {
   128	            throw notAllowed(reservation, "confirm");
   129	        }
   130	        reservation.confirmPayment();
   131	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
   132	        emailSender.send(
   133	                reservation.guest().email(),
   134	                "Reserva confirmada - " + HOTEL_NAME,
   135	                confirmationEmailBody(reservation, receipt));
   136	        return reservation;
   137	    }
   138	
   139	    /**
   140	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
   141	     * reservation was never paid, so nothing comes back).
   142	     */
   143	    public synchronized Reservation cancel(long reservationId) {
   144	        Reservation reservation = find(reservationId);
   145	        if (reservation.status() != ReservationStatus.PENDING
   146	                && reservation.status() != ReservationStatus.CONFIRMED) {
   147	            throw notAllowed(reservation, "cancel");
   148	        }
   149	        BigDecimal refund = ratePlans.policyFor(reservation.ratePlan()).refund(reservation);
   150	        reservation.cancel(refund);
   151	        return reservation;
   152	    }
   153	
   154	    public synchronized Reservation checkIn(long reservationId) {
   155	        Reservation reservation = find(reservationId);
   156	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   157	            throw notAllowed(reservation, "check in");
   158	        }
   159	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   160	        return reservation;
   161	    }
   162	
   163	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   164	    public synchronized ReservationReceipt checkOut(long reservationId) {
   165	        Reservation reservation = find(reservationId);
   166	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   167	            throw notAllowed(reservation, "check out");
   168	        }
   169	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   170	        return new ReservationReceipt(reservation, roomOf(reservation));
   171	    }
   172	
   173	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   174	    public ReservationReceipt receiptCopy(long reservationId) {
   175	        Reservation reservation = find(reservationId);
   176	        if (!reservation.isPaid()) {
   177	            throw notAllowed(reservation, "issue a receipt for");
   178	        }
   179	        return new ReservationReceipt(reservation, roomOf(reservation));
   180	    }
   181	
   182	    private Room roomOf(Reservation reservation) {
   183	        return rooms.find(reservation.roomNumber()).orElseThrow();
   184	    }
   185	
   186	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   187	        return "Olá, " + reservation.guest().name() + "!\n\n"
   188	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   189	                + receipt.text() + "\n"
   190	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   191	                + "Até breve!\n";
   192	    }
   193	
   194	    private static HotelException notAllowed(Reservation reservation, String operation) {
   195	        return new HotelException(
   196	                ErrorCode.OPERATION_NOT_ALLOWED,
   197	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   198	    }
   199	}
# Pousada Maré Alta: o sistema de reservas

O serviço que a pousada usa para as reservas: o site cria e confirma as reservas, a recepção faz o
check-in e o check-out, e o contador tira os relatórios.

## Como rodar

```bash
mvn verify
```

```bash
java -jar target/hotel.jar
```

O serviço sobe na porta 7070 (ou na que estiver em `PORT`). Os dados ficam em memória: quando o
serviço reinicia, as reservas se perdem.

## Como funciona

- **Quartos:** cinco, de três tipos (`STANDARD`, `DELUXE`, `SUITE`), cada um com a sua capacidade e a
  sua diária.
- **Preço:** cada noite custa a diária do quarto. Na alta temporada (de 15 de dezembro ao fim de
  fevereiro, e o mês de julho inteiro), a noite custa 20% a mais. O plano `NON_REFUNDABLE` dá 15% de
  desconto sobre a soma das noites. O dinheiro é arredondado para centavos, meio para o par, a cada passo.
- **Reserva:** nasce `PENDING`. Quando o hóspede paga, é confirmada (`CONFIRMED`), e ele recebe o
  comprovante por e-mail. Depois vêm o check-in (`CHECKED_IN`) e o check-out (`CHECKED_OUT`), que
  entrega o comprovante final.
- **Cancelamento:** só antes do check-in. No plano `STANDARD`, o hóspede recebe de volta o que pagou;
  no `NON_REFUNDABLE`, não recebe nada.
- **Mensagens:** os e-mails enviados ficam guardados, e a recepção os consulta em `/messages`.
- **Relatórios (CSV):** a ocupação de uma noite, para a recepção, e o dinheiro que ficou com a pousada
  das reservas que começam num mês, para o contador.

## A API

| | |
|---|---|
| `GET /rooms` | os quartos |
| `POST /reservations` | cria uma reserva |
| `GET /reservations/{id}` | uma reserva |
| `POST /reservations/{id}/confirmation` | confirma (o hóspede pagou) |
| `POST /reservations/{id}/cancellation` | cancela |
| `POST /reservations/{id}/check-in` | registra a entrada |
| `POST /reservations/{id}/check-out` | registra a saída e devolve o comprovante final |
| `GET /reservations/{id}/document` | a segunda via do comprovante |
| `GET /messages` | as mensagens enviadas |
| `GET /reports/occupancy?date=2027-07-10` | a ocupação de uma noite |
| `GET /reports/revenue?month=2027-07` | o financeiro de um mês |

O corpo de `POST /reservations`:

```json
{
  "roomNumber": 201,
  "guestName": "Carla Dias",
  "guestEmail": "carla@example.com",
  "guestCpf": "111.222.333-44",
  "checkIn": "2027-07-10",
  "checkOut": "2027-07-12",
  "guests": 2,
  "ratePlan": "STANDARD"
}
```

Os erros vêm como `{"error": "<código>", "message": "..."}`:

| código | status | quando |
|---|---|---|
| `INVALID_REQUEST` | 400 | falta um campo, o corpo não é JSON, ou a saída não é depois da entrada |
| `ROOM_NOT_FOUND` | 404 | o quarto não existe |
| `RESERVATION_NOT_FOUND` | 404 | a reserva não existe |
| `ROOM_UNAVAILABLE` | 409 | o quarto já está reservado em alguma das noites |
| `OPERATION_NOT_ALLOWED` | 409 | a reserva não está na situação que a operação pede |
| `CAPACITY_EXCEEDED` | 422 | mais hóspedes do que o quarto comporta |

